\title{Dense Asymptotic Invisibility in the Infinite Symmetric Group\\
\large Finite-Prefix Extension, Prime-Indexed Sequences, and Factorial Families}
\author{Aristotle}
\date{July 18, 2026}

\begin{document}
\maketitle

\begin{abstract}
Let $S_\infty$ be the group of permutations of the nonnegative integers with the topology of pointwise convergence. Given an eventually nonzero real sequence $a=(a_n)_{n\ge0}$, call a permutation $\sigma$ ratio-one if $a_{\sigma(n)}/a_n\to1$. We prove that ratio-one permutations are dense in $S_\infty$. Every prescribed finite prefix of an arbitrary permutation extends to a permutation that is eventually the identity; its rearranged-to-original quotient is therefore eventually exactly one. The argument is independent of growth, monotonicity, and arithmetic structure, and applies in particular to every prime-valued enumeration. Lehmer codes additionally give $k!$ distinct infinite permutations supported on the first $k$ indices, all ratio-one for every eventually nonzero sequence. We present constructive algorithms, complexity bounds, numerical illustrations, and a careful distinction between topological density and probabilistic prevalence.
\end{abstract}

\section{Introduction}
Hilbert's Hotel models countable infinity by rooms indexed by $\N=\{0,1,2,\ldots\}$. If room $n$ contains a quantity $a_n$, a permutation $\sigma:\N\to\N$ places $a_{\sigma(n)}$ in room $n$. The relative visibility of this move is measured by
\[
r_n(\sigma;a)=\frac{a_{\sigma(n)}}{a_n}.
\]
We ask which permutations become asymptotically invisible, meaning that this ratio tends to one.

When $a_n=p_n$ is prime, it is tempting to invoke the asymptotic growth of the increasing primes. The density result here needs no prime asymptotics. Its mechanism is finite and combinatorial: arbitrary prescribed behavior on finitely many inputs can be closed into a permutation of a finite set, after which every remaining input is fixed.

This gives a precise but limited conclusion. Every pointwise neighborhood contains a ratio-one permutation. Density neither says that every permutation is good nor assigns a probability to good permutations. The result separates the topology of infinite rearrangements from the harder arithmetic classification of infinitely supported prime rearrangements.

\section{Definitions and topology}

\begin{definition}
A \emph{permutation} of $\N$ is a bijection $\sigma:\N\to\N$. The infinite symmetric group $S_\infty$ is the collection of all such permutations. Its support is
\[
\supp(\sigma)=\{n\in\N:\sigma(n)\ne n\}.
\]
It has finite support, equivalently is \emph{eventually fixed}, when some $N$ satisfies $\sigma(n)=n$ for every $n\ge N$.
\end{definition}

For $\sigma\in S_\infty$ and $k\in\N$, define the prefix cylinder
\[
U(\sigma,k)=\{\tau\in S_\infty:\tau(n)=\sigma(n)\text{ for every }n<k\}.
\]
These cylinders form a neighborhood basis for pointwise convergence. Arbitrary finite sets of observed inputs cause no difficulty because each is contained in an initial segment.

\begin{definition}
A set $G\subseteq S_\infty$ is \emph{prefix-dense} if $G\cap U(\sigma,k)\ne\varnothing$ for every $\sigma\in S_\infty$ and $k\in\N$. This is equivalent to density in the pointwise topology.
\end{definition}

\begin{definition}
Let $a:\N\to\R$ be eventually nonzero. A permutation $\sigma$ is \emph{asymptotically invisible} or \emph{ratio-one} for $a$ if
\[
\lim_{n\to\infty}\frac{a_{\sigma(n)}}{a_n}=1.
\]
The collection of these permutations is denoted $W(a)$.
\end{definition}

Eventual nonvanishing is the minimal tail condition needed for the displayed real quotient; finitely many exceptional values do not affect convergence.

\section{Finite-prefix extension}

\begin{theorem}[Finite-Prefix Extension]
For every $\sigma\in S_\infty$ and $k\in\N$, there exists $\tau\in S_\infty$ such that
\[
\tau(n)=\sigma(n)\quad(0\le n<k)
\]
and $\tau$ is eventually fixed.
\end{theorem}

\begin{proof}[Proof sketch]
Choose $N$ larger than $k$ and every member of the finite list $\sigma(0),\ldots,\sigma(k-1)$. Set
\[
X=\{0,\ldots,k-1\},\qquad Y=\{0,\ldots,N-1\}.
\]
The restriction $f=\sigma|_X:X\to Y$ is injective. The unused source set $Y\setminus X$ and unused target set $Y\setminus f(X)$ both contain $N-k$ elements, so choose a bijection $g$ between them. Combining $f$ and $g$ gives a bijection $\rho:Y\to Y$. Define
\[
\tau(n)=\begin{cases}\rho(n),&n<N,\\ n,&n\ge N.\end{cases}
\]
The two regions are invariant and the first restriction is bijective, so $\tau$ is a permutation. It agrees with $\sigma$ below $k$ and fixes the entire tail. For $k=0$, the identity suffices.
\end{proof}

\begin{corollary}
Finite-support permutations are dense in $S_\infty$ with its pointwise topology.
\end{corollary}
\begin{proof}[Proof sketch]
The preceding theorem supplies a finite-support member of every prefix cylinder.
\end{proof}

The prescribed images need not lie in the first $k$ positions. Enlarging to $Y$ is what absorbs them while allowing the unseen part of the permutation to be changed.

\section{Dense asymptotic invisibility}

\begin{lemma}[Tail Identity]
If $a:\N\to\R$ is eventually nonzero and $\tau\in S_\infty$ is eventually fixed, then $\tau\in W(a)$.
\end{lemma}

\begin{proof}[Proof sketch]
Choose $N_0$ such that $a_n\ne0$ for $n\ge N_0$ and $N_1$ such that $\tau(n)=n$ for $n\ge N_1$. For $n\ge\max(N_0,N_1)$,
\[
\frac{a_{\tau(n)}}{a_n}=\frac{a_n}{a_n}=1.
\]
Thus the quotient is eventually constant at one.
\end{proof}

\begin{theorem}[Dense Asymptotic-Invisibility]
Let $a:\N\to\R$ be eventually nonzero. Then $W(a)$ is prefix-dense in $S_\infty$. Explicitly, for every $\sigma\in S_\infty$ and $k\in\N$, there is $\tau\in S_\infty$ such that
\[
\tau(n)=\sigma(n)\quad(n<k),\qquad
\lim_{n\to\infty}\frac{a_{\tau(n)}}{a_n}=1.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Extend the prescribed prefix to an eventually fixed $\tau$ using the Finite-Prefix Extension Theorem, then apply the Tail Identity Lemma.
\end{proof}

The constructed quotient is not merely convergent: it is exactly one on a tail. The extension itself depends only on $\sigma$ and $k$, not on $a$, so one extension works simultaneously for every eventually nonzero real sequence.

\section{Prime-valued sequences}

Let $p:\N\to\N$ be prime-valued. No monotonicity or distinctness hypothesis is needed below, though the increasing enumeration of all primes is the motivating example.

\begin{theorem}[Prime-Hotel Density]
For every prime-valued sequence $(p_n)_{n\ge0}$, every $\sigma\in S_\infty$, and every $k\in\N$, there exists $\tau\in S_\infty$ such that
\[
\tau(n)=\sigma(n)\quad(n<k)
\]
and
\[
\lim_{n\to\infty}\frac{p_{\tau(n)}}{p_n}=1.
\]
Hence asymptotically invisible prime rearrangements are dense in the pointwise topology.
\end{theorem}

\begin{proof}[Proof sketch]
Every prime is at least two, so the real sequence $a_n=p_n$ is everywhere nonzero. Apply the Dense Asymptotic-Invisibility Theorem.
\end{proof}

Primality enters only through nonvanishing. The theorem does not require the prime number theorem or even infinitude of primes once a prime-valued sequence is given. It also does not assert that every permutation is ratio-one. Infinitely many macroscopic index displacements may destroy convergence.

Density is not probability. There is no uniform probability measure on all permutations of $\N$ analogous to the uniform law on a finite symmetric group. A dense set can also be meagre. The conclusion is instead that no finite observation can rule out a good continuation.

\section{Factorial families from Lehmer codes}

For $k\ge0$, a Lehmer code is a tuple $(c_0,\ldots,c_{k-1})$ with
\[
0\le c_i<k-i.
\]
Begin with the ordered list $[0,1,\ldots,k-1]$. Select and remove the entry at position $c_0$, then at position $c_1$ in the shortened list, and continue. This decodes a unique permutation of the first $k$ indices. Conversely, recording each selected element's rank among unused elements recovers the code. The number of codes is
\[
\prod_{i=0}^{k-1}(k-i)=k!.
\]

\begin{theorem}[Factorial Family]
For every $k$, Lehmer codes produce $k!$ distinct permutations of $\N$ supported in $\{0,\ldots,k-1\}$. Every one is asymptotically invisible for every eventually nonzero real sequence.
\end{theorem}

\begin{proof}[Proof sketch]
Lehmer coding is a bijection with the permutations of $k$ symbols. Extend each finite permutation by the identity for $n\ge k$. If two finite permutations differ, their extensions differ below $k$, so extension is injective. Every extension is eventually fixed, and the Tail Identity Lemma applies.
\end{proof}

Thus local complexity grows factorially while every member of the family has the same trivial tail ratio.

\section{Algorithms and complexity}

\subsection{Prefix completion}
Given distinct targets $v_0,\ldots,v_{k-1}$, take
\[
N=1+\max(\{k\}\cup\{v_i:0\le i<k\}).
\]
Mark the prescribed targets, scan $0,\ldots,N-1$ to list unused targets, and pair these in order with the unused sources $k,\ldots,N-1$. The resulting array is a permutation of the first $N$ indices; extend it by the identity. A Boolean marking array gives $O(N+k)$ time and $O(N)$ memory.

\subsection{Lehmer decoding}
Maintain an ordered list of unused symbols and remove the entry selected by each code digit. A simple list implementation uses $O(k^2)$ time and $O(k)$ memory. An order-statistic tree lowers the time to $O(k\log k)$.

\subsection{Ratio profiles}
For known values $a_0,\ldots,a_{M-1}$ and a finite permutation array, compute $a_{\tau(n)}/a_n$ whenever the denominator is nonzero. Unlisted indices of an identity extension have ratio one. Evaluation costs $O(M)$ time and can stream output using $O(1)$ additional space.

\section{Numerical illustration}
Prescribe
\[
(\sigma(0),\sigma(1),\sigma(2))=(3,0,4).
\]
Taking $N=5$, pair unused sources $3,4$ with unused targets $1,2$. This yields
\[
\tau=(3,0,4,1,2),
\]
followed by the identity. For the increasing primes
\[
2,3,5,7,11,13,17,19,\ldots,
\]
the ratio profile is
\[
\frac72,\ \frac23,\ \frac{11}{5},\ \frac37,\ \frac5{11},\ 1,\ 1,\ 1,\ldots.
\]
The finite disturbance is large, but all later ratios are exactly one. Likewise, the $6!=720$ finite permutations of the first six indices give $720$ distinct prime rearrangements whose ratios equal one from index six onward.

\section{Random rearrangements and interpretation}
A uniformly random permutation of $\{0,\ldots,M-1\}$ is well defined. If it is extended by the identity, its infinite ratio sequence automatically converges to one, irrespective of its first $M$ values. If instead a fresh permutation is drawn for each growing $M$, one obtains a triangular array rather than one infinite permutation unless a coupling is specified.

Consequently, experiments on random finite permutations cannot determine an exact density or probability of well-behaved infinite permutations. A probability question requires an explicit infinite model, such as regenerative block permutations. Finite-mean local blocks may force relative displacement to vanish, while heavy-tailed blocks may create infinitely many macroscopic jumps. These possibilities are separate from topological density.

For the increasing primes, the asymptotic relation $p_n\sim n\log n$ suggests a deeper criterion:
\[
\frac{\sigma(n)}n\to1
\quad\Longleftrightarrow\quad
\frac{p_{\sigma(n)}}{p_n}\to1.
\]
Proving this for arbitrary nonmonotone permutations would classify the full ratio-one class and explain why local swaps can work despite having infinite support.

\section{Applications and extensions}
The result is sequence-independent. The same finite-prefix extension is harmless for stock-price sequences, frequencies, masses, or other real measurements whenever denominators are eventually nonzero. In data analysis it models finitely many relabelings or index errors and shows that ratio-based tail behavior ignores them.

An algebraic extension replaces nonzero real values by units in a topological monoid or group. If $x_n$ is eventually invertible, then an eventually fixed permutation makes $x_{\tau(n)}x_n^{-1}$ eventually equal to the identity. This identifies eventual invertibility, rather than primality or order, as the operative condition.

\section{Future directions}
Natural questions include the Baire-category size of the ratio-one prime rearrangements; realization of every positive limiting ratio $c$; an abstract unit-group criterion; the equivalence between relative index displacement and relative prime displacement; and phase transitions in regenerative random-permutation models. The finite-extension theorem supplies the dense half of these investigations and ensures that arbitrary finite constraints can be incorporated into later block constructions.

\section{Structural consequences}
The construction gives simultaneous approximation. For fixed $\sigma$ and $k$, the resulting $\tau$ is eventually fixed independently of the sequence, so the same extension is asymptotically invisible for every eventually nonzero real sequence, including an arbitrary uncountable family of them.

Each prefix cylinder also contains infinitely many ratio-one permutations. After constructing an extension supported below $N$, compose it with any permutation supported in a later finite interval $\{N,\ldots,M-1\}$. The composition preserves the prescribed prefix and remains eventually fixed. Letting $M$ grow gives finite subfamilies of unbounded factorial size.

The assumptions have distinct roles: injectivity permits finite matching; finite subsets of $\N$ fit below a cutoff; eventual nonvanishing makes tail division meaningful; and eventual fixation forces the limit. Primality contributes only nonvanishing.

\section{Conclusion}
Every finite observation of a permutation of $\N$ extends to an eventually fixed permutation. Hence finite-support permutations are dense in the pointwise topology. Eventual fixation makes every rearranged-to-original quotient eventually exactly one, so ratio-one permutations are dense for every eventually nonzero real sequence and for every prime-valued enumeration. Lehmer codes exhibit $k!$ distinct examples supported on the first $k$ rooms. The conclusion is topological rather than probabilistic: no finite window can exclude asymptotic invisibility, and any true obstruction must arise through behavior repeated arbitrarily far along the sequence.

\end{document}

