from typing import Sequence

def decode_lehmer(code: Sequence[int]) -> list[int]:
    available = list(range(len(code)))
    result: list[int] = []
    for digit in code:
        if not 0 <= digit < len(available):
            raise ValueError("invalid Lehmer code")
        result.append(available.pop(digit))
    return result

if __name__ == "__main__":
    print(decode_lehmer([2, 0, 1, 0]))

from typing import Sequence

def complete_prefix(prefix: Sequence[int]) -> list[int]:
    """Complete distinct images to a finite permutation, then extend by identity."""
    if any(x < 0 for x in prefix) or len(set(prefix)) != len(prefix):
        raise ValueError("prefix must contain distinct nonnegative targets")
    size = max(len(prefix), max(prefix, default=-1) + 1)
    used = set(prefix)
    return list(prefix) + [x for x in range(size) if x not in used]

if __name__ == "__main__":
    print(complete_prefix([3, 0, 4]))

