from typing import Sequence

def ratio_profile(values: Sequence[float], tau: Sequence[int]) -> list[float]:
    if len(values) != len(tau) or any(v == 0 for v in values):
        raise ValueError("equal lengths and nonzero values are required")
    return [values[tau[n]] / values[n] for n in range(len(values))]

if __name__ == "__main__":
    primes = [2., 3., 5., 7., 11., 13.]
    print(ratio_profile(primes, [3, 0, 4, 1, 2, 5]))

